CREATE TABLE IF NOT EXISTS gis_spatial_qa_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, check_name text NOT NULL, status text NOT NULL DEFAULT 'Pending', expected_value text, actual_value text, details text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_dataset_activation_readiness (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES gis_boundary_datasets(id) ON DELETE CASCADE, source_verified boolean NOT NULL DEFAULT false, feature_count_ok boolean NOT NULL DEFAULT false, geometry_validated boolean NOT NULL DEFAULT false, code_crosswalk_validated boolean NOT NULL DEFAULT false, qa_passed boolean NOT NULL DEFAULT false, activation_ready boolean NOT NULL DEFAULT false, evaluated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_spatial_qa_dataset ON gis_spatial_qa_results(dataset_id,status);
CREATE INDEX IF NOT EXISTS idx_gis_activation_readiness_dataset ON gis_dataset_activation_readiness(dataset_id,evaluated_at DESC);